		tmpDirAbs = paths.EntireTmpDir
	}
	return filepath.Join(tmpDirAbs, fmt.Sprintf("pre-prompt-%s.json", sessionID))
}

// preTaskStateFile returns the absolute path to the pre-task state file for a tool use.
