	tmpDir := t.TempDir()
	transcriptPath := filepath.Join(tmpDir, "sess-123.json")

	// Create an existing file with stale data
	if err := os.WriteFile(transcriptPath, []byte(`{"info":{},"messages":[]}`), 0o600); err != nil {
